// ============================================================================
// mvdr_board_top.v -- Board-level top, Real Digital Boolean Board (XC7S50-CSGA324)
// Strict Verilog-2001 (the MMCME2_BASE / BUFG are Xilinx primitives).
//
// CHANGE vs. the previous version: the MVDR core now runs from a 50 MHz clock
// generated by an MMCM from the 100 MHz board clock. Reason: the solver's
// pivot-decision path (accumulate -> round -> saturate -> compare -> div_d CE)
// is ~13.3 ns long, which fails at 10 ns. At 20 ns it passes with ~6 ns slack.
// Nothing else changes: same ports (so the XDC pin constraints stay valid),
// same core, same cycle counts, same results.
//
// Ports : clk (100 MHz), btn_rst, btn_start (active high), led[3:0]
// LEDs  : led[0] busy, led[1] done, led[2] any status flag,
//         led[3] XOR of a running checksum over every output sample
//
// To change the core clock: Fcore = 100 MHz * MMCM_MULT / MMCM_DIV
//   (VCO = 100 * MMCM_MULT must stay within 600..1200 MHz for a -1 device)
//   50 MHz   : MULT 10.0, DIV 20.0   (default, safest)
//   66.67 MHz: MULT 10.0, DIV 15.0   (only ~1.5 ns slack with the current solver)
// ============================================================================

`timescale 1ns/1ps

module mvdr_board_top #(
    parameter BLOCK_LEN   = 76,
    parameter NUM_SAMPLES = 1536,
    parameter MEM_DEPTH   = 2048,
    parameter MEM_FILE    = "x_mem.mem",
    parameter real MMCM_MULT = 10.0,   // VCO = 100 MHz * 10 = 1000 MHz
    parameter real MMCM_DIV  = 20.0    // 1000 / 20 = 50 MHz
)(
    input  wire       clk,         // 100 MHz board clock
    input  wire       btn_rst,     // push button, active high
    input  wire       btn_start,   // push button, active high
    output wire [3:0] led
);

    // ------------------------------------------------------------------------
    // Clock generation: 100 MHz -> core clock (50 MHz)
    // ------------------------------------------------------------------------
    wire clk_fb;
    wire clk_core_unbuf;
    wire clk_core;
    wire mmcm_locked;

    MMCME2_BASE #(
        .BANDWIDTH        ("OPTIMIZED"),
        .CLKIN1_PERIOD    (10.0),
        .DIVCLK_DIVIDE    (1),
        .CLKFBOUT_MULT_F  (MMCM_MULT),
        .CLKOUT0_DIVIDE_F (MMCM_DIV),
        .CLKFBOUT_PHASE   (0.0),
        .CLKOUT0_PHASE    (0.0),
        .CLKOUT0_DUTY_CYCLE (0.5),
        .STARTUP_WAIT     ("FALSE")
    ) u_mmcm (
        .CLKIN1    (clk),
        .CLKFBIN   (clk_fb),
        .CLKFBOUT  (clk_fb),
        .CLKFBOUTB (),
        .CLKOUT0   (clk_core_unbuf),
        .CLKOUT0B  (),
        .CLKOUT1   (),
        .CLKOUT1B  (),
        .CLKOUT2   (),
        .CLKOUT2B  (),
        .CLKOUT3   (),
        .CLKOUT3B  (),
        .CLKOUT4   (),
        .CLKOUT5   (),
        .CLKOUT6   (),
        .LOCKED    (mmcm_locked),
        .PWRDWN    (1'b0),
        .RST       (1'b0)
    );

    BUFG u_bufg_core (
        .I (clk_core_unbuf),
        .O (clk_core)
    );

    // ------------------------------------------------------------------------
    // Everything below runs in the core clock domain.
    // Reset is held while the MMCM is unlocked, then for 16 more cycles,
    // and whenever the reset button is pressed.
    // ------------------------------------------------------------------------
    reg [1:0] lock_sync = 2'b00;
    always @(posedge clk_core) begin
        lock_sync <= {lock_sync[0], mmcm_locked};
    end
    wire core_ok = lock_sync[1];

    reg [4:0] por_cnt = 5'd0;
    wire      por     = ~por_cnt[4];

    always @(posedge clk_core) begin
        if (!core_ok)
            por_cnt <= 5'd0;
        else if (por)
            por_cnt <= por_cnt + 5'd1;
    end

    // 2-flop synchronizers for the buttons + rising-edge start pulse
    reg [1:0] rst_sync   = 2'b00;
    reg [1:0] start_sync = 2'b00;
    reg       start_d    = 1'b0;

    always @(posedge clk_core) begin
        rst_sync   <= {rst_sync[0],   btn_rst};
        start_sync <= {start_sync[0], btn_start};
        start_d    <= start_sync[1];
    end

    reg rst = 1'b1;
    always @(posedge clk_core) begin
        rst <= por | rst_sync[1] | ~core_ok;
    end

    wire start_pulse = start_sync[1] & ~start_d;

    // ------------------------------------------------------------------------
    // MVDR core -- every port is an internal wire (no package pins)
    // ------------------------------------------------------------------------
    wire         m_valid;
    wire [47:0]  m_data;
    wire         m_last;
    wire [15:0]  m_idx;
    wire [7:0]   m_blk;
    wire         m_is_tail;
    wire         busy;
    wire         done;
    wire [7:0]   status;

    (* DONT_TOUCH = "true" *)
    mvdr_top #(
        .BLOCK_LEN   (BLOCK_LEN),
        .NUM_SAMPLES (NUM_SAMPLES),
        .MEM_DEPTH   (MEM_DEPTH),
        .MEM_FILE    (MEM_FILE),
        .PACED       (0)
    ) u_core (
        .clk              (clk_core),
        .rst              (rst),
        .start            (start_pulse),
        .sample_en        (1'b0),      // unused in free-run mode (PACED = 0)
        .m_ready          (1'b1),      // always accept output (no backpressure)

        .m_valid          (m_valid),
        .m_data           (m_data),
        .m_last           (m_last),
        .m_idx            (m_idx),
        .m_blk            (m_blk),
        .m_is_tail        (m_is_tail),
        .busy             (busy),
        .done             (done),
        .status           (status),

        // Debug ports left unconnected
        .dbg_w_active     (),
        .dbg_w_swap       (),
        .dbg_blk_done     (),
        .dbg_solve_cycles (),
        .dbg_state        ()
    );

    // ------------------------------------------------------------------------
    // Running checksum over every accepted output sample
    // ------------------------------------------------------------------------
    wire [74:0] out_word = {m_is_tail, m_last, m_blk, m_idx, m_data, 1'b0};

    reg [74:0] checksum = 75'd0;
    always @(posedge clk_core) begin
        if (rst)
            checksum <= 75'd0;
        else if (m_valid)
            checksum <= {checksum[73:0], checksum[74]} ^ out_word;
    end

    // ------------------------------------------------------------------------
    // LEDs
    // ------------------------------------------------------------------------
    assign led[0] = busy;
    assign led[1] = done;
    assign led[2] = |status;
    assign led[3] = ^checksum;

endmodule